/**
 * AutoLing — Klein-inspired meta-symbolic language learning & generation engine.
 *
 * Based on Sheldon Klein's work:
 *   - "Automatic Novel Writing" (1973, UWCS Tech Report 186)
 *   - "Modelling Propp and Lévi-Strauss in a Meta-symbolic Simulation System" (1974)
 *   - "Analogical Foundations of Creativity in Language, Culture & the Arts" (2002)
 *
 * Klein's key principles implemented here:
 *   1. Boolean feature vectors on ALL units (semantic objects, relations, rules)
 *   2. Production rules stored AS DATA — same rules used for generation & recognition
 *   3. Bidirectional feature inheritance (features flow up AND down grammar trees)
 *   4. Meta-symbolic: the system can reason about its own grammar
 *   5. Analogy: new structures generated by analogical mapping over existing ones
 *
 * EXTENDED with learning (Klein's systems were mostly static grammars):
 *   - Learns English (and any natural language) from text
 *   - Learns CODE as a formal language (JavaScript, Python, etc.)
 *   - Distributes learned grammar via the mesh (P2P)
 *   - Every unit in the system accumulates feature weight from exposure
 *
 * The system treats CODE as a language — with its own grammar, lexicon,
 * and semantic structures — no different from natural language in principle.
 */

import { v4 as uuidv4 } from 'uuid';
import { BY_FUXI } from '../data/hexagrams.js';
import { MorphoAnalyzer } from './MorphoAnalyzer.js';
import { SemNet } from './SemNet.js';
import { Disseminer, ITEM_TYPES } from './Disseminer.js';
import { ToolFactory, LEVELS } from './ToolFactory.js';

// ── Feature vector dimensions ─────────────────────────────────────────────────
// All units carry a Boolean/continuous feature vector.
// Natural language features:
const NL_FEATURES = [
  'isNoun','isVerb','isAdj','isAdv','isPronoun','isPrep','isConj',
  'isAnimate','isConcrete','isAbstract','isAction','isState','isRelation',
  'isPast','isPresent','isFuture','isActive','isPassive',
  'isSingular','isPlural','isPositive','isNegative','isQuestion',
];
// Code features:
const CODE_FEATURES = [
  'isFunction','isClass','isVariable','isLoop','isConditional','isReturn',
  'isAsync','isGenerator','isPure','hasSideEffect','hasState','hasIO',
  'isHigherOrder','isRecursive','isClosure','isDeclaration','isExpression',
  'isJS','isPython','isTypeScript','isShell','isJSON','isMarkdown',
  'readsFile','writesFile','callsNetwork','callsDB','emitsEvent','listensEvent',
];
// I Ching / hexagram semantic features (bridge between symbol and language):
const ICHING_FEATURES = [
  'isYang','isYin','isChanging','isUpper','isLower','isNuclear','isComplement',
  'isTrigram','isHexagram','isLine','isGate','isChannel',
];

export const ALL_FEATURES = [...NL_FEATURES, ...CODE_FEATURES, ...ICHING_FEATURES];
const FEATURE_DIM = ALL_FEATURES.length;

// ── Lexical Unit ──────────────────────────────────────────────────────────────
class LexUnit {
  constructor(form, features = {}) {
    this.id = uuidv4();
    this.form = form;           // surface form (word, token, AST node type...)
    this.weight = 1;            // exposure count / confidence
    this.features = {};
    ALL_FEATURES.forEach(f => {
      this.features[f] = features[f] ?? 0;
    });
    this.relations = [];        // LexUnit relations (semantic network edges)
    this.createdAt = Date.now();
  }

  // Compute Boolean feature vector as array
  featureVector() {
    return ALL_FEATURES.map(f => this.features[f] > 0.5 ? 1 : 0);
  }

  // Analogy score against another unit (Hamming similarity on feature vectors)
  analogyScore(other) {
    const a = this.featureVector();
    const b = other.featureVector();
    const matches = a.reduce((s, v, i) => s + (v === b[i] ? 1 : 0), 0);
    return matches / FEATURE_DIM;
  }

  addRelation(type, targetId, weight = 1) {
    this.relations.push({ type, targetId, weight });
  }
}

// ── Production Rule ───────────────────────────────────────────────────────────
// Rules are DATA — same rule can generate or recognize (bidirectional).
class ProductionRule {
  constructor(lhs, rhs, features = {}, language = 'universal') {
    this.id = uuidv4();
    this.lhs = lhs;    // left-hand symbol (string)
    this.rhs = rhs;    // right-hand sequence (array of strings/objects)
    this.weight = 1;   // learned confidence
    this.language = language;
    this.features = features; // feature constraints
    this.generationCount = 0;
    this.recognitionCount = 0;
  }

  // Apply rule in generation mode — expand lhs into rhs
  generate(context = {}) {
    this.generationCount++;
    this.weight *= 1.001; // reinforce
    return this.rhs.map(sym => {
      if (typeof sym === 'function') return sym(context);
      return sym;
    });
  }

  matches(featureQuery) {
    return Object.entries(featureQuery).every(([k, v]) => {
      return Math.abs((this.features[k] ?? 0) - v) < 0.3;
    });
  }
}

// ── Grammar ───────────────────────────────────────────────────────────────────
class Grammar {
  constructor(language = 'universal') {
    this.language = language;
    this.rules = new Map();     // lhs → [ProductionRule]
    this.lexicon = new Map();   // form → LexUnit
    this.learnCount = 0;
  }

  addRule(rule) {
    if (!this.rules.has(rule.lhs)) this.rules.set(rule.lhs, []);
    this.rules.get(rule.lhs).push(rule);
  }

  addUnit(unit) {
    this.lexicon.set(unit.form, unit);
  }

  getUnit(form) { return this.lexicon.get(form); }

  // Get rules matching a feature query, weighted by confidence
  getRules(lhs, featureQuery = {}) {
    const candidates = this.rules.get(lhs) || [];
    return candidates
      .filter(r => Object.keys(featureQuery).length === 0 || r.matches(featureQuery))
      .sort((a, b) => b.weight - a.weight);
  }

  /**
   * Learn from a chunk of text or code.
   * This extracts n-gram patterns and creates/strengthens production rules.
   */
  learn(text, language = null) {
    const lang = language || this.language;
    const tokens = this._tokenize(text, lang);
    this.learnCount++;

    // Learn bigram and trigram production rules
    for (let n = 2; n <= 3; n++) {
      for (let i = 0; i <= tokens.length - n; i++) {
        const window = tokens.slice(i, i + n);
        const lhs = this._classify(window[0], lang);
        const rhs = window.slice(1).map(t => t);

        const existingRules = this.rules.get(lhs) || [];
        const rhsStr = rhs.join(' ');
        const existing = existingRules.find(r => r.rhs.join(' ') === rhsStr);
        if (existing) {
          existing.weight += 0.1;
        } else {
          const rule = new ProductionRule(lhs, rhs, { learned: 1 }, lang);
          this.addRule(rule);
        }

        // Add to lexicon
        window.forEach(tok => {
          if (!this.lexicon.has(tok)) {
            const unit = new LexUnit(tok, this._inferFeatures(tok, lang));
            this.addUnit(unit);
          } else {
            this.lexicon.get(tok).weight += 0.05;
          }
        });
      }
    }

    // If code, extract structural patterns
    if (['javascript','python','typescript'].includes(lang)) {
      this._learnCodeStructures(text, lang);
    }

    return { tokens: tokens.length, rules: this.rules.size, lexicon: this.lexicon.size };
  }

  _tokenize(text, language) {
    if (['javascript','python','typescript'].includes(language)) {
      // Code tokenization: split on code boundaries
      return text
        .replace(/\/\/[^\n]*/g, '')      // strip comments
        .replace(/\/\*[\s\S]*?\*\//g, '')
        .split(/[\s\n\r,;()\[\]{}]+/)
        .filter(t => t.length > 0 && t.length < 80);
    }
    // Natural language tokenization
    return text
      .toLowerCase()
      .replace(/[^a-z0-9\s'-]/g, ' ')
      .split(/\s+/)
      .filter(t => t.length > 1);
  }

  _classify(token, language) {
    // Map token to a grammatical category (LHS symbol)
    if (['javascript','python','typescript'].includes(language)) {
      if (/^(function|def|const|let|var|class|async|export|import)$/.test(token)) return 'DECL';
      if (/^(if|else|switch|case|for|while|do|try|catch|finally)$/.test(token)) return 'CTRL';
      if (/^(return|yield|await|throw|break|continue)$/.test(token)) return 'FLOW';
      if (/^[A-Z][a-zA-Z]+$/.test(token)) return 'TYPE';
      if (/^[a-z][a-zA-Z]+$/.test(token)) return 'ID';
      if (/^\d+/.test(token)) return 'NUM';
      if (/^['"`]/.test(token)) return 'STR';
      return 'OP';
    }
    // English
    const NL_MAP = {
      VERB: ['is','are','was','were','be','been','do','does','did','have','has','had',
             'can','could','will','would','shall','should','may','might','must',
             'make','take','get','give','see','know','think','come','go','say'],
      DET: ['the','a','an','this','that','these','those','my','your','his','her','its'],
      PREP: ['in','on','at','to','for','with','by','from','of','about','into','through'],
      CONJ: ['and','but','or','nor','so','yet','because','if','when','while','although'],
      PRON: ['i','you','he','she','it','we','they','me','him','her','us','them'],
    };
    for (const [cat, words] of Object.entries(NL_MAP)) {
      if (words.includes(token)) return cat;
    }
    return 'NOUN'; // default
  }

  _inferFeatures(token, language) {
    const f = {};
    if (['javascript','python','typescript'].includes(language)) {
      f.isJS = language === 'javascript' ? 1 : 0;
      f.isPython = language === 'python' ? 1 : 0;
      f.isTypeScript = language === 'typescript' ? 1 : 0;
      f.isFunction = /^(function|def|=>|lambda)$/.test(token) ? 1 : 0;
      f.isClass = /^(class|Class)$/.test(token) ? 1 : 0;
      f.isAsync = /^(async|await|Promise)$/.test(token) ? 1 : 0;
      f.isLoop = /^(for|while|forEach|map|reduce|filter)$/.test(token) ? 1 : 0;
      f.isConditional = /^(if|else|switch|ternary|\?)$/.test(token) ? 1 : 0;
    }
    return f;
  }

  _learnCodeStructures(code, language) {
    // Extract function signatures as production rules
    const fnPatterns = {
      javascript: /(?:async\s+)?function\s+(\w+)\s*\(([^)]*)\)/g,
      typescript: /(?:async\s+)?function\s+(\w+)\s*\(([^)]*)\)/g,
      python: /def\s+(\w+)\s*\(([^)]*)\)/g,
    };
    const pat = fnPatterns[language];
    if (!pat) return;

    let m;
    while ((m = pat.exec(code)) !== null) {
      const [_, name, params] = m;
      const paramList = params.split(',').map(p => p.trim()).filter(Boolean);
      const rule = new ProductionRule(
        'FUNCTION_DEF',
        [name, '(', ...paramList, ')'],
        { isFunction: 1, learned: 1 },
        language
      );
      rule.weight = 2; // higher confidence for explicit structures
      this.addRule(rule);

      const unit = new LexUnit(name, { isFunction: 1 });
      this.addUnit(unit);
    }
  }

  toJSON() {
    return {
      language: this.language,
      ruleCount: this.rules.size,
      lexiconSize: this.lexicon.size,
      learnCount: this.learnCount,
    };
  }
}

// ── AutoDev: Code Generation Variant ─────────────────────────────────────────
class AutoDev {
  constructor(grammar) {
    this.grammar = grammar;
    this.templates = this._seedTemplates();
    this.generatedTools = [];
  }

  _seedTemplates() {
    return [
      {
        id: 'function_template',
        name: 'Pure Function',
        features: { isFunction: 1, isPure: 1 },
        generate: (ctx) => `
// AutoDev: Generated from hexagram ${ctx.fromChar} → ${ctx.toChar} (${ctx.fromName} → ${ctx.toName})
// Changing line ${ctx.changingLines?.map(l => l.lineNumber).join(',')} — ${ctx.layer} layer
export function ${ctx.toolName}(input) {
  // ${ctx.fromName}: ${ctx.fromKeyword}
  // → ${ctx.toName}: ${ctx.toKeyword}
  const state = { input, origin: '${ctx.fromFuxi}', target: '${ctx.toFuxi}' };
  return transform(state);
}

function transform(state) {
  // Learned from changing line — adapt this logic
  return Object.assign({}, state, { processed: true, ts: Date.now() });
}
`.trim(),
      },
      {
        id: 'class_template',
        name: 'Stateful Module',
        features: { isClass: 1, hasState: 1 },
        generate: (ctx) => `
// AutoDev: Generated from ${ctx.fromName} → ${ctx.toName} via ${ctx.layer}
export class ${ctx.toolName} {
  constructor(config = {}) {
    this.origin = { fuxi: ${ctx.fromFuxi}, name: '${ctx.fromName}', char: '${ctx.fromChar}' };
    this.target = { fuxi: ${ctx.toFuxi}, name: '${ctx.toName}', char: '${ctx.toChar}' };
    this.config = config;
    this.state = {};
    this.history = [];
  }

  process(input) {
    const result = this._transform(input);
    this.history.push({ input, result, ts: Date.now() });
    return result;
  }

  _transform(input) {
    // Changing line ${ctx.changingLines?.map(l => l.lineNumber + '(' + l.type + ')').join(', ')}
    return { data: input, origin: this.origin, target: this.target };
  }

  learn(example) {
    // AutoLing learning: add example to internal grammar
    this.state[Date.now()] = example;
  }

  toJSON() {
    return { origin: this.origin, target: this.target, historyLength: this.history.length };
  }
}
`.trim(),
      },
      {
        id: 'event_template',
        name: 'Event Emitter Tool',
        features: { emitsEvent: 1, isAsync: 1 },
        generate: (ctx) => `
// AutoDev: Event tool — ${ctx.fromName}(${ctx.fromChar}) → ${ctx.toName}(${ctx.toChar})
import { EventEmitter } from 'events';

export class ${ctx.toolName} extends EventEmitter {
  constructor() {
    super();
    this.signature = { from: ${ctx.fromFuxi}, to: ${ctx.toFuxi}, layer: '${ctx.layer}' };
  }

  async activate(data) {
    this.emit('before', { signature: this.signature, data });
    const result = await this._run(data);
    this.emit('after', { signature: this.signature, result });
    return result;
  }

  async _run(data) {
    // Generated by AutoLing changing-line engine
    // Line(s): ${ctx.changingLines?.map(l => l.lineNumber).join(',')}
    return { transformed: data, signature: this.signature, ts: Date.now() };
  }

  learn(codeString) {
    // Inject learned behavior dynamically
    this.emit('learned', { code: codeString.slice(0, 100) });
  }
}
`.trim(),
      },
      {
        id: 'grammar_tool',
        name: 'Language Grammar Tool',
        features: { isFunction: 1, isPure: 1, hasState: 1 },
        generate: (ctx) => `
// AutoDev: Grammar/language tool — ${ctx.fromName} → ${ctx.toName}
// Inspired by Klein's meta-symbolic grammar (1973, 1976)

const GRAMMAR_${ctx.toolName.toUpperCase()} = {
  origin: { fuxi: ${ctx.fromFuxi}, name: '${ctx.fromName}', char: '${ctx.fromChar}' },
  target: { fuxi: ${ctx.toFuxi}, name: '${ctx.toName}', char: '${ctx.toChar}' },
  language: 'universal',
  rules: [],
  lexicon: new Map(),

  learn(text, language = 'english') {
    const tokens = text.toLowerCase().split(/\\s+/).filter(t => t.length > 1);
    tokens.forEach((tok, i) => {
      if (!this.lexicon.has(tok)) this.lexicon.set(tok, { form: tok, weight: 1 });
      else this.lexicon.get(tok).weight += 0.1;
      if (i < tokens.length - 1) {
        this.rules.push({ lhs: tok, rhs: tokens[i + 1], weight: 1, language });
      }
    });
    return { learned: tokens.length, rules: this.rules.length };
  },

  generate(seed = null) {
    if (this.rules.length === 0) return '';
    let current = seed || [...this.lexicon.keys()][Math.floor(Math.random() * this.lexicon.size)];
    const output = [current];
    for (let i = 0; i < 20; i++) {
      const nexts = this.rules.filter(r => r.lhs === current);
      if (nexts.length === 0) break;
      const total = nexts.reduce((s, r) => s + r.weight, 0);
      let rand = Math.random() * total;
      const chosen = nexts.find(r => (rand -= r.weight) <= 0) || nexts[0];
      current = chosen.rhs;
      output.push(current);
    }
    return output.join(' ');
  },
};

export default GRAMMAR_${ctx.toolName.toUpperCase()};
`.trim(),
      },
    ];
  }

  selectTemplate(context, hexagonFeatures) {
    // Pick template by analogy: find closest feature match
    const query = {
      isAsync: hexagonFeatures?.changingLines?.some(l => l.lineNumber >= 4) ? 1 : 0,
      hasState: hexagonFeatures?.changingLines?.length > 2 ? 1 : 0,
      emitsEvent: hexagonFeatures?.layer === 'Temporal' ? 1 : 0,
    };
    // Use Klein-style analogical selection (weighted random among top-scoring)
    const scored = this.templates.map(t => ({
      t,
      score: Object.entries(query).reduce(
        (s, [k, v]) => s + Math.abs((t.features[k] || 0) - v),
        0
      ),
    })).sort((a, b) => a.score - b.score);

    // Weighted selection: top 2 templates
    const topScore = scored[0].score;
    const candidates = scored.filter(s => s.score <= topScore + 1);
    return candidates[Math.floor(Math.random() * candidates.length)].t;
  }

  generate(context) {
    const template = this.selectTemplate(context, context);
    const code = template.generate(context);
    return { templateId: template.id, templateName: template.name, code };
  }
}

// ── AutoLing (main engine) — Level 7 Circuit tool ────────────────────────────
// Composed of three Level-4 Trigram sub-tools:
//   Sub-tool 1: MorphoAnalyzer — morphological analysis
//   Sub-tool 2: SemNet         — semantic network (relational calculus)
//   Sub-tool 3: Disseminer     — broadcast / mesh distribution
// Plus: AutoDev (code generator), ToolFactory (level-aware tool creation)
export class AutoLing {
  constructor() {
    // Multiple grammars — one per language (Klein: system can contain multiple grammars)
    this.grammars = {
      universal:  new Grammar('universal'),
      english:    new Grammar('english'),
      javascript: new Grammar('javascript'),
      python:     new Grammar('python'),
      typescript: new Grammar('typescript'),
    };

    // ── Three core sub-tools (Level 4 — Trigram) ──
    this.morpho     = new MorphoAnalyzer(null, 'universal');  // Sub-tool 1
    this.semnet     = new SemNet();                           // Sub-tool 2
    this.disseminer = new Disseminer();                       // Sub-tool 3

    // ── Level 5-6: AutoDev code generator ──
    this.autoDev = new AutoDev(this.grammars.universal);

    // ── Level-aware ToolFactory ──
    this.toolFactory = new ToolFactory();

    this.toolCount = 0;
    this.meshQueue = [];

    // Wire Disseminer subscriptions
    this._wireSubscriptions();

    // Seed grammars
    this._seedEnglish();
    this._seedJavaScript();

    console.log('[AutoLing] initialized — 3 sub-tools (MorphoAnalyzer + SemNet + Disseminer)');
    console.log('[AutoLing] grammars:', Object.keys(this.grammars).join(', '));
  }

  _wireSubscriptions() {
    // When a tool is published via Disseminer, learn from its code
    this.disseminer.subscribe(
      Disseminer.filterByType(ITEM_TYPES.TOOL),
      (item) => {
        if (item.data?.code) this.learn(item.data.code, 'javascript');
      }
    );
    // When a grammar update arrives, teach SemNet
    this.disseminer.subscribe(
      Disseminer.filterByType(ITEM_TYPES.GRAMMAR_UPDATE),
      (item) => {
        if (item.data?.tokens) {
          this.semnet.learn(item.data.tokens, item.language);
        }
      }
    );
  }

  /**
   * Learn from any text or code string.
   * Routes to Grammar + MorphoAnalyzer + SemNet simultaneously.
   */
  learn(text, languageHint = null) {
    const language = languageHint || this._detectLanguage(text);
    const grammar  = this.grammars[language] || this.grammars.universal;
    const result   = grammar.learn(text, language);

    // Cross-pollinate universal grammar
    if (language !== 'universal') {
      this.grammars.universal.learn(text, language);
    }

    // Sub-tool 1: MorphoAnalyzer learns tokens
    const tokens = text.toLowerCase().split(/\s+/).filter(t => t.length > 1);
    this.morpho.learn(tokens);

    // Sub-tool 2: SemNet learns token co-occurrences
    this.semnet.learn(tokens, language);

    // Sub-tool 3: Disseminer broadcasts the grammar update
    this.disseminer.publish(ITEM_TYPES.GRAMMAR_UPDATE, { tokens: tokens.slice(0, 20), result }, { language });

    this.meshQueue.push({ type: 'grammar_update', language, result, ts: Date.now() });

    return { language, ...result };
  }

  /**
   * Generate a tool from a changing-line event.
   * Uses ToolFactory to select the correct level based on the event.
   * Each tool is unique to its origin address + changing line combination.
   */
  async generate(event, model) {
    const fromHex = BY_FUXI[event.fromFuxi];
    const toHex   = BY_FUXI[event.toFuxi];
    if (!fromHex || !toHex) return null;

    // Use ToolFactory for level-aware generation
    const factoryTool = this.toolFactory.generate(event, null);

    // Also generate via AutoDev (Level 5-6 templates)
    const context = {
      ...event,
      toolName: factoryTool.name,
      fromKeyword: fromHex.keyword,
      toKeyword: toHex.keyword,
    };
    const generated = this.autoDev.generate(context);

    // SemNet: record the transformation as a semantic relation
    const fromId = `gate_${fromHex.kw}`;
    const toId   = `gate_${toHex.kw}`;
    if (!this.semnet.nodes.has(fromId))
      this.semnet.addNode(fromId, fromHex.name, { isGate: 1, isHexagram: 1 });
    if (!this.semnet.nodes.has(toId))
      this.semnet.addNode(toId, toHex.name, { isGate: 1, isHexagram: 1 });
    this.semnet.addEdge(fromId, toId, 'CHANGES_TO', 1, { isChanging: 1 });

    // MorphoAnalyzer: analyze the hexagram names
    this.morpho.learn([fromHex.name, toHex.name, fromHex.keyword, toHex.keyword]);

    const description = this._generateDescription(context);

    const tool = {
      ...factoryTool,
      description,
      code: factoryTool.level >= 5 ? generated.code : factoryTool.code,
      templateId: generated.templateId,
      templateName: generated.templateName,
      levelName: LEVELS[factoryTool.level]?.name || 'Tool',
    };

    // Feed generated code back into AutoLing (self-improvement loop)
    setTimeout(() => {
      this.learn(tool.code, 'javascript');
      tool.learned = true;
    }, 100);

    // Disseminer broadcasts the new tool
    this.disseminer.publish(ITEM_TYPES.TOOL, tool, {
      originAddress: tool.address,
      language: 'javascript',
    });

    this.toolCount++;
    this.autoDev.generatedTools.push(tool);
    this.meshQueue.push({ type: 'tool', tool, ts: Date.now() });

    return tool;
  }

  /**
   * Drain the mesh queue — called by P2P layer to distribute learnings.
   */
  drainMeshQueue() {
    const items = [...this.meshQueue];
    this.meshQueue = [];
    return items;
  }

  /**
   * Receive a grammar update from the mesh (another instance's learnings).
   */
  receiveFromMesh(item) {
    if (item.type === 'grammar_update') {
      // Merge: strengthen existing rules or add new ones
      const grammar = this.grammars[item.language] || this.grammars.universal;
      grammar.learnCount += item.result?.tokens || 0;
    } else if (item.type === 'tool') {
      // Learn from a tool generated by another instance
      if (item.tool?.code) {
        this.learn(item.tool.code, 'javascript');
      }
    }
  }

  _detectLanguage(text) {
    const t = text.slice(0, 500);
    if (/\bdef\s+\w+\s*\(|import\s+\w+\s*$|\bprint\s*\(/.test(t)) return 'python';
    if (/\bfunction\s+\w+|const\s+\w+\s*=|=>\s*{|\bimport\s*{/.test(t)) return 'javascript';
    if (/:\s*(string|number|boolean|void|any)\b|interface\s+\w+/.test(t)) return 'typescript';
    return 'english';
  }

  _makeName(fromHex, toHex, changingLines) {
    const lineNums = (changingLines || []).map(l => l.lineNumber).join('');
    const base = `${fromHex.name.replace(/\s+/g, '')}To${toHex.name.replace(/\s+/g, '')}`;
    const suffix = lineNums ? `L${lineNums}` : '';
    return `${base}${suffix}Tool`;
  }

  _generateDescription(ctx) {
    // Simple natural-language generation using learned English grammar
    const grammar = this.grammars.english;
    const seeds = [
      `This tool transforms ${ctx.fromName} into ${ctx.toName}.`,
      `Generated when ${ctx.fromChar} (${ctx.fromKeyword}) changes to ${ctx.toChar} (${ctx.toKeyword}).`,
      `Changing ${ctx.changingLines?.length || 0} line(s) in the ${ctx.layer} layer.`,
    ];
    // Try to extend with learned grammar
    const generated = grammar.rules.size > 0
      ? grammar.getRules('VERB').slice(0, 1).map(r => r.rhs.join(' ')).join(' ')
      : '';
    return seeds.join(' ') + (generated ? ' ' + generated : '');
  }

  _seedEnglish() {
    const seed = `
    the system generates tools from changing lines in the hexagram network
    each tool is unique to its origin and transforms input into output
    the grammar learns from every text and code it encounters
    language is the medium through which the mesh communicates
    boolean features describe every unit in the semantic network
    analogy maps new structures onto existing ones to create meaning
    the changing line signals a transformation in the state space
    knowledge flows through the layers connecting all nodes
    `.trim();
    this.grammars.english.learn(seed, 'english');
    this.grammars.universal.learn(seed, 'english');
  }

  _seedJavaScript() {
    const seed = `
    const transform = (input) => ({ ...input, processed: true });
    async function generate(context) { return await transform(context); }
    class Tool extends EventEmitter { constructor() { super(); this.state = {}; } }
    export function learn(text) { return tokenize(text).map(classify); }
    const features = ALL_FEATURES.map(f => ({ name: f, value: 0 }));
    `.trim();
    this.grammars.javascript.learn(seed, 'javascript');
  }

  getStats() {
    return {
      grammars: Object.fromEntries(
        Object.entries(this.grammars).map(([k, g]) => [k, g.toJSON()])
      ),
      subTools: {
        morpho:     this.morpho.toJSON(),
        semnet:     this.semnet.toJSON(),
        disseminer: this.disseminer.getStats(),
      },
      toolFactory: this.toolFactory.getStats(),
      toolCount: this.toolCount,
      meshQueueLength: this.meshQueue.length,
    };
  }
}
